// one‑time macro to refresh all items that use a given template. It updates // the template version and injects any missing props (so your new field or  // edit gets added), without overwriting existing values.

(async () => {
  const TEMPLATE_ID = "WpDhy1PMWFkO6tOc";
  const TEMPLATE_NAME = "Firearms Template";

  const template =
    game.items?.get?.(TEMPLATE_ID) ||
    game.items?.find?.(i => i?.name === TEMPLATE_NAME && i?.type === "_equippableItemTemplate") ||
    null;

  if (!template) {
    ui.notifications?.error?.(
      `Template refresh: template not found. Expected id ${TEMPLATE_ID} or name "${TEMPLATE_NAME}".`
    );
    return;
  }

  const tProps = template.system?.props ?? {};
  const tVersion = template.system?.templateSystemUniqueVersion;

  const items = (game.items?.filter?.(i => i?.system?.template === template.id) ?? []);
  if (!items.length) {
    ui.notifications?.warn?.("Template refresh: no items found using this template.");
    return;
  }

  let updated = 0;
  let addedFields = 0;
  let refreshed = 0;

  for (const item of items) {
    const update = {};

    if (tVersion && item.system?.templateSystemUniqueVersion !== tVersion) {
      update["system.templateSystemUniqueVersion"] = tVersion;
    }

    if (item.system?.template !== template.id) {
      update["system.template"] = template.id;
    }

    for (const [k, v] of Object.entries(tProps)) {
      if (item.system?.props?.[k] === undefined) {
        update[`system.props.${k}`] = v ?? "";
        addedFields += 1;
      }
    }

    if (Object.keys(update).length) {
      await item.update(update);
      updated += 1;

      if (item.sheet?.rendered) {
        item.sheet.render(true);
        refreshed += 1;
      }
    }
  }

  ui.notifications?.info?.(
    `Template refresh: updated ${updated} item(s), added ${addedFields} missing field(s), refreshed ${refreshed} open sheet(s).`
  );
})();
